// Shape of content/case-studies/<slug>.json (generated by scripts/import-framer.py).

export type Img = { src: string; alt: string };
export type Card = { label: string; value: string };

export type Block =
  | { type: "heading"; text: string }
  | { type: "paragraph"; text: string }
  | { type: "list"; items: string[] }
  | { type: "images"; images: Img[] }
  | { type: "cards"; cards: Card[] }
  | { type: "video"; vimeoId: string }
  | { type: "embed"; src: string };

export type Section = { label: string; blocks: Block[] };

export type CaseStudy = {
  slug: string;
  title: string;
  description: string;
  tags: string[];
  hmw: string; // completes the sentence "How might we …"
  facts: Card[]; // values may contain "\n" line breaks
  prototype: { embed: string; link: string | null } | null;
  heroImages: Img[];
  sections: Section[]; // a section's label may be "" (untitled intro section)
  unportedComponents: string[];
  imageCount: number;
};
